def parse(text):
    try:
        value = int(text)
    except ValueError:
        return "不是整数"
    else:
        return value * 2
    finally:
        print("清理")


print(parse("21"))
print(parse("x"))

class ConfigError(Exception):
    pass


def load(value):
    if value < 0:
        raise ConfigError(f"配置不能为负：{value}")
    return value


try:
    load(-1)
except ConfigError as exc:
    print(type(exc).__name__, exc)

